   WORKDIR /app

   COPY . .

   RUN npm install cypress

   COPY package*.json ./

   RUN npm install

   COPY cypress cypress

   RUN npm install -g cypress

   EXPOSE 4444

   CMD ["cypress", "run", "--spec", "cypress/integration/*.spec.js"]
